/* Bluegum Digital Services (IT & ITeS) - source database seed for the pipeline Copy demo
   Plays the role of: ITSM and service catalogue database (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.client_services; DROP TABLE IF EXISTS src.incidents; DROP TABLE IF EXISTS src.stage_client_services; DROP TABLE IF EXISTS src.stage_incidents;
CREATE TABLE src.client_services (service_id INT NOT NULL, contract_ref NVARCHAR(30), service_name NVARCHAR(100), service_line NVARCHAR(30), delivery_centre NVARCHAR(40), status NVARCHAR(30), sla_tier INT, monthly_fee_aud DECIMAL(12,1), contract_start DATE, last_modified DATETIME2(0), CONSTRAINT pk_client_services PRIMARY KEY (service_id));
CREATE TABLE src.incidents (incident_id INT NOT NULL, service_id INT, category NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), resolved_ts DATETIME2(0), sla_penalty_aud DECIMAL(12,2), effort_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_incidents PRIMARY KEY (incident_id));
CREATE TABLE src.stage_client_services (release_day INT NOT NULL, service_id INT, contract_ref NVARCHAR(30), service_name NVARCHAR(100), service_line NVARCHAR(30), delivery_centre NVARCHAR(40), status NVARCHAR(30), sla_tier INT, monthly_fee_aud DECIMAL(12,1), contract_start DATE, last_modified DATETIME2(0), delivery_lead NVARCHAR(50));
CREATE TABLE src.stage_incidents (release_day INT NOT NULL, incident_id INT, service_id INT, category NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), resolved_ts DATETIME2(0), sla_penalty_aud DECIMAL(12,2), effort_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.client_services', 'delivery_lead') IS NULL
        EXEC('ALTER TABLE src.client_services ADD delivery_lead NVARCHAR(50) NULL');
    DELETE t FROM src.client_services t WHERE EXISTS (SELECT 1 FROM src.stage_client_services s WHERE s.release_day = @day AND s.service_id = t.service_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.delivery_lead = s.delivery_lead FROM src.client_services t JOIN src.stage_client_services s ON s.service_id = t.service_id AND s.release_day = 3');
    DELETE t FROM src.incidents t WHERE EXISTS (SELECT 1 FROM src.stage_incidents s WHERE s.release_day = @day AND s.incident_id = t.incident_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.client_services) AS client_services, (SELECT COUNT(*) FROM src.incidents) AS incidents;
END;
GO
