    INSERT INTO src.client_services (service_id, contract_ref, service_name, service_line, delivery_centre, status, sla_tier, monthly_fee_aud, contract_start, last_modified) SELECT service_id, contract_ref, service_name, service_line, delivery_centre, status, sla_tier, monthly_fee_aud, contract_start, last_modified FROM src.stage_client_services WHERE release_day = @day;
    INSERT INTO src.incidents (incident_id, service_id, category, priority, status, opened_ts, resolved_ts, sla_penalty_aud, effort_hours, description, last_modified) SELECT incident_id, service_id, category, priority, status, opened_ts, resolved_ts, sla_penalty_aud, effort_hours, description, last_modified FROM src.stage_incidents WHERE release_day = @day;
